from 写入第二遍 import add
add('16_002',2,'16:9，高空俯看武士上半身的中全景，武士头居画面中央上方，两条巨大手臂垂向左右下角，远处林海铺在身下；摄影机随上升渐缓，落幅把头和臂端外缘留全。','武士的上升速度开始放缓，头胸沿惯性向下垂，双臂在两侧落成沉重弧线；擦伤轮廓旁几枚深灰细屑继续向下拖走。他把气憋到肩头一缩，低短痛叫从胸腔顶出，白眼朝身下扫过，第一次看清与林海间拉开的高度。','灰绿森林冠层铺满下方远景，树团密而细，越远越淡；地平远端接蓝灰云层与一线浅冷灰雾。','高处开阔云天冷白柔光均匀照到背肩，巨大身体下侧偏冷灰，林海在薄雾中降低对比。','拉长的风声渐薄，武士肩部缩动的低沉气响，细屑向下擦过。',ja=['くっ！！'],tone='武士上踢后的短痛叫，压在胸腔里，起音重而收得快。',kind='mixed',phase='reaction',node={'叙事阶段':'武士升到高处，痛叫并向下看','武士.位置':'林海之上，升势渐缓'},meaning='武士高空俯身、两臂下垂与林海背景保留，痛叫在尚未落地的高度发生。',motion='身体上升趋缓，头胸下垂，细屑向下；摄影机跟升后放慢。',ground='全身离地，身下远处林海无接触。',characters=['鬼头武士'])
add('16_003',8,'16:9，武士低头的正面头肩近景，白眼落在中央黑隙中，两肩向左右伸出画幅；机位随身体轻微升沉，落幅维持由上方看其头肩的角度。','武士先用白眼搜向下方，眼隙绷开，第一句质问急急顶出；他想端正头部，肩颈刚抬起便牵到擦伤，停住一拍。第二句转回惯有的下流猜测，白眼斜移，试着把方才的惊慌压成判断；话尾一阵风从下方卷上，眼珠又向来路猛地回扫，肩膀随之绷紧。','两肩之间与下沿只有浅蓝灰云天，极近轮廓之外为淡冷灰云雾，林海留在画外下方。','云天冷白漫射在额顶和肩顶形成宽亮面，擦痕以深灰短线保留，眼隙深黑。','高处稀薄风声，肩颈用力时一声短沉呼吸，镜尾由下而上的破风渐近。',ja=['この力はどこから湧いてきた？！','こいつ、外では清楚で、内では淫らなタイプなのか？！'],tone='武士第一句惊怒急问；第二句强作猜测，仍带原作粗俗语气，尾句被接近的风声牵动注意。',kind='mixed',phase='reaction',node={'叙事阶段':'武士质问力量来源，青从下方追近'},meaning='武士低头正面、白眼与两句原作质问保留，版外中英注释不入配音。',motion='武士在高空缓慢升沉，眼神向下方来路移动。',ground='仍离地，身体只有惯性升沉，不新增支点。',characters=['鬼头武士'],card={'opening':'武士试图理解自己忽然落入的劣势。','beats':['搜向下方急问','欲抬头牵动擦伤，停一拍','以粗俗猜测掩饰惊慌，随近风回扫'],'coupling':'第一句泄出惊怒，第二句试夺回判断权，逼近的声音又打断稳定。','landing':'白眼锁向追来的方向，肩颈绷紧。'})
add('17_001',2,'16:9，仰看高空的极远景，武士小黑影位于画面中央上方，一条长白锥形轨迹从左下通向影子下方；镜头沿轨迹缓慢上仰，落幅把顶端黑影留在中央上部。','武士小黑影在高处升势将尽，两条臂形向下弯；下方白色细尖骤然沿长轨向他逼近，轨迹两侧的细线被向后抽长。细尖临近黑影下缘时，白弧从画面右下掠出，云纹在镜头上仰中缓缓下移，下一镜才看清追到的青。','深浅蓝灰云层占满天空，细白速度粒在云隙散开，白色长锥周围留出平缓冷灰空隙。','高处云天冷白漫射，远端黑影与白轨形成清晰对比，云层保持同一日间色调。','从低处直拔上来的长破风越逼越近，临近顶端时突然收成短而锐的一声。',phase='process',node={'叙事阶段':'青追到武士所在高度','青.位置':'由下方向武士头侧高速接近'},meaning='高空小黑影与长白追近轨迹保留，到下一原镜才揭示青已在头旁。',motion='白轨自左下向顶端逼近，摄影机沿同一方向上仰；黑影几乎停在升势顶点。',ground='双方均在高空，平台不入画。',characters=['鬼头武士'])
